import { describe, it, expect } from "vitest";
import { attachControl, createArcRotateCamera } from "@babylonjs/lite";
import type { SceneContext } from "@babylonjs/lite";
import { attachFastOrbit } from "./fast-orbit.ts";

function fakeCanvas() {
    const map = new Map<string, Set<any>>();
    return {
        map,
        addEventListener(ev: string, h: any) { if (!map.has(ev)) map.set(ev, new Set()); map.get(ev)!.add(h); },
        removeEventListener(ev: string, h: any) { map.get(ev)?.delete(h); },
        setPointerCapture() {},
        releasePointerCapture() {},
        count() { let n = 0; for (const s of map.values()) n += s.size; return n; },
        fire(ev: string, e: any) { for (const h of [...(map.get(ev) ?? [])]) h(e); },
    } as any;
}
function run(kind: "lib" | "fast") {
    const cam = createArcRotateCamera(0.5, 1.0, 10, { x: 0, y: 0, z: 0 } as any);
    const canvas = fakeCanvas();
    const scene = { _beforeRender: [] as (() => void)[] } as unknown as SceneContext;
    const detach = kind === "lib" ? attachControl(cam, canvas, scene) : attachFastOrbit(cam, canvas, scene);
    const a0 = cam.alpha, b0 = cam.beta;
    canvas.fire("pointerdown", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 100, clientY: 100 });
    canvas.fire("pointermove", { pointerId: 1, clientX: 130, clientY: 60 });
    canvas.fire("pointerup", { pointerId: 1 });
    const dA1 = cam.alpha - a0, dB1 = cam.beta - b0;
    for (let i = 0; i < 200; i++) for (const h of [...scene._beforeRender]) h();
    return { dA1, dB1, dAall: cam.alpha - a0, dBall: cam.beta - b0, cam, canvas, scene, detach };
}
describe("fast orbit", () => {
    it("doubles drag and glide", () => {
        const lib = run("lib"), fast = run("fast");
        expect(fast.dA1 / lib.dA1).toBeCloseTo(2, 9);
        expect(fast.dB1 / lib.dB1).toBeCloseTo(2, 9);
        expect(fast.dAall / lib.dAall).toBeCloseTo(2, 6);
        expect(fast.dBall / lib.dBall).toBeCloseTo(2, 6);
        expect(lib.cam.angularSensibility).toBe(1000);
    });
    it("cleans up", () => {
        const f = run("fast");
        expect(f.canvas.count()).toBeGreaterThan(0);
        f.detach(); f.detach();
        expect(f.canvas.count()).toBe(0);
        expect(f.scene._beforeRender.length).toBe(0);
        expect(f.cam.angularSensibility).toBe(1000);
    });
});
EOF
